ci_fallback_post_fp_inc:
	MOVQ    CTX_FRAME_POINTER(R15), CX
	DECQ    CX
	MOVQ    CX, CTX_FRAME_POINTER(R15)

ci_fallback:
	DECQ    R14
	MOVQ    R14, CTX_PC(R15)
	MOVQ    $EXIT_CALL, CTX_EXIT_REASON(R15)
	MOVQ    R14, CTX_EXIT_PC(R15)
	RET     

ci_overflow:
	DECQ    R14
	MOVQ    R14, CTX_PC(R15)
	MOVQ    $EXIT_CALL_OVERFLOW, CTX_EXIT_REASON(R15)
	MOVQ    R14, CTX_EXIT_PC(R15)
	RET     

// handlerCallMethodInline handles opCallMethod with a per-site receiver-type table and the ASM-inlined fast path.
TEXT ·handlerCallMethodInline(SB), NOSPLIT|NOFRAME, $0
	INCQ    R14
	MOVQ    DX, CX
	SHRQ    $16, CX

	MOVQ    CTX_ASM_CALL_INFO_BASE(R15), AX
	TESTQ   AX, AX
	JZ      ci_fallback
	SHLQ    $ACI_SIZE_SHIFT, CX
	LEAQ    (AX)(CX*1), AX

	MOVQ    ACI_METHOD_ENTRY_COUNT(AX), CX
	TESTQ   CX, CX
	JZ      ci_fallback
	CMPB    CTX_HAS_GOROUTINES(R15), $0
	JNE     ci_fallback
	MOVQ    ACI_RECEIVER_REG(AX), SI
	MOVQ    CTX_GENERALS_BASE(R15), DI
	LEAQ    (SI)(SI*2), SI
	MOVQ    (DI)(SI*8), SI
	TESTQ   SI, SI
	JZ      ci_fallback
	MOVBQZX ABI_TYPE_KIND_BYTE(SI), DX
	ANDQ    $FLAG_KIND_MASK, DX
	CMPQ    DX, $REFLECT_INTERFACE
	JE      ci_fallback
	CMPQ    DX, $REFLECT_POINTER
	JNE     ci_method_scan
	MOVQ    ABI_TYPE_PTR_ELEM(SI), SI
ci_method_scan:
	XORQ    DX, DX
ci_method_loop:
	CMPQ    (ACI_METHOD_TYPE_WORDS)(AX)(DX*8), SI
	JE      ci_method_hit
	INCQ    DX
	CMPQ    DX, CX
	JL      ci_method_loop
	JMP     ci_fallback
ci_method_hit:
	SHLQ    $ACI_SIZE_SHIFT, DX
	MOVQ    ACI_METHOD_ENTRIES_PTR(AX), AX
	LEAQ    (AX)(DX*1), AX

	CMPQ    ACI_IS_FAST_PATH(AX), $0
	JE      ci_fallback

	MOVQ    ACI_CLOSURE_PTR(AX), BX
	TESTQ   BX, BX
	JZ      ci_static_entry
	CMPB    CTX_HAS_GOROUTINES(R15), $0
	JNE     ci_fallback
	MOVQ    ACI_CLOSURE_REG(AX), CX
	MOVQ    CTX_GENERALS_BASE(R15), SI
	LEAQ    (CX)(CX*2), CX
	LEAQ    (SI)(CX*8), SI
	MOVQ    16(SI), CX
	MOVQ    8(SI), SI
	TESTQ   $0x80, CX
	JZ      ci_closure_direct
	MOVQ    (SI), SI
ci_closure_direct:
	CMPQ    SI, BX
	JNE     ci_fallback
ci_static_entry:

	MOVQ    CTX_FRAME_POINTER(R15), SI
	LEAQ    1(SI), DI
	CMPQ    DI, CTX_DEPTH_LIMIT(R15)
	JGE     ci_overflow

	CMPQ    DI, CTX_CSTACK_LEN(R15)
	JGE     ci_fallback

	MOVQ    CTX_ARENA_INT_IDX(R15), BX
	ADDQ    ACI_CALLEE_NUM_INTS(AX), BX
	CMPQ    BX, CTX_ARENA_INT_CAP(R15)
	JG      ci_fallback

	MOVQ    CTX_ARENA_FLT_IDX(R15), BX
	ADDQ    ACI_CALLEE_NUM_FLOATS(AX), BX
	CMPQ    BX, CTX_ARENA_FLT_CAP(R15)
	JG      ci_fallback

	MOVQ    CTX_DISPATCH_SAVES(R15), BX
	MOVQ    SI, CX
	SHLQ    $DS_SIZE_SHIFT, CX
	LEAQ    (BX)(CX*1), BX
	MOVQ    R12, DS_CODE_BASE(BX)
	MOVQ    R13, DS_CODE_LEN(BX)
	MOVQ    R11, DS_INT_CONSTS(BX)
	MOVQ    CTX_FLT_CONSTS_BASE(R15), CX
	MOVQ    CX, DS_FLOAT_CONSTS(BX)
	MOVQ    CTX_STR_CONSTS_BASE(R15), CX
	MOVQ    CX, DS_STRING_CONSTS(BX)
	MOVQ    CTX_BOOL_CONSTS_BASE(R15), CX
	MOVQ    CX, DS_BOOL_CONSTS(BX)
	MOVQ    CTX_UINT_CONSTS_BASE(R15), CX
	MOVQ    CX, DS_UINT_CONSTS(BX)

	MOVQ    CTX_CSTACK_BASE(R15), BX
	MOVQ    $CALLFRAME_SIZE, CX
	IMULQ   SI, CX
	LEAQ    (BX)(CX*1), CX
	MOVQ    R14, CF_PROGRAM_COUNTER(CX)

	MOVQ    $CALLFRAME_SIZE, DX
	IMULQ   DI, DX
	LEAQ    (BX)(DX*1), BX

	MOVQ    DI, CTX_FRAME_POINTER(R15)
	MOVQ    BX, CTX_CURRENT_FRAME(R15)

	MOVQ    $0, CF_SHARED_CELLS(BX)
	MOVW    $0xFFFF, CF_REGS_LAST_MASK(BX)
	MOVQ    ACI_UPVALS_PTR(AX), CX
	MOVQ    CX, CF_UPVALUES_PTR(BX)
	MOVQ    ACI_UPVALS_LEN(AX), CX
	MOVQ    CX, (CF_UPVALUES_PTR+8)(BX)
	MOVQ    ACI_UPVALS_CAP(AX), CX
	MOVQ    CX, (CF_UPVALUES_PTR+16)(BX)

	MOVQ    CTX_ARENA_INT_IDX(R15), CX
	MOVQ    CX, (CF_ARENA_SAVE+0)(BX)
	MOVQ    CTX_ARENA_FLT_IDX(R15), CX
	MOVQ    CX, (CF_ARENA_SAVE+8)(BX)
	MOVQ    CTX_ARENA_STR_IDX(R15), CX
	MOVQ    CX, (CF_ARENA_SAVE+16)(BX)
	MOVQ    CTX_ARENA_GEN_IDX(R15), CX
	MOVQ    CX, (CF_ARENA_SAVE+24)(BX)
	MOVQ    CTX_ARENA_BOOL_IDX(R15), CX
	MOVQ    CX, (CF_ARENA_SAVE+32)(BX)
	MOVQ    CTX_ARENA_UINT_IDX(R15), CX
	MOVQ    CX, (CF_ARENA_SAVE+40)(BX)
	MOVQ    CTX_ARENA_CPLX_IDX(R15), CX
	MOVQ    CX, (CF_ARENA_SAVE+48)(BX)
	MOVQ    CTX_ARENA_SLICEINT_IDX(R15), CX
	MOVQ    CX, (CF_ARENA_SAVE+56)(BX)
	MOVQ    CTX_ARENA_SLICEFLT_IDX(R15), CX
	MOVQ    CX, (CF_ARENA_SAVE+64)(BX)
	MOVQ    CTX_ARENA_SLICESTR_IDX(R15), CX
	MOVQ    CX, (CF_ARENA_SAVE+72)(BX)
	MOVQ    CTX_ARENA_SLICEBOOL_IDX(R15), CX
	MOVQ    CX, (CF_ARENA_SAVE+80)(BX)
	MOVQ    CTX_ARENA_SLICEUINT_IDX(R15), CX
	MOVQ    CX, (CF_ARENA_SAVE+88)(BX)
	MOVQ    CTX_ARENA_SLICEBYTE_IDX(R15), CX
	MOVQ    CX, (CF_ARENA_SAVE+96)(BX)

	MOVQ    CTX_ARENA_INT_IDX(R15), CX
	MOVQ    CTX_ARENA_INT_SLAB(R15), DX
	LEAQ    (DX)(CX*8), DX
	MOVQ    ACI_CALLEE_NUM_INTS(AX), DI
