	MOVQ    DI, CF_REGS_INTS_CAP(BX)
	ADDQ    DI, CX
	MOVQ    CX, CTX_ARENA_INT_IDX(R15)

	MOVQ    CTX_ARENA_FLT_IDX(R15), CX
