	MOVB    $1, CTX_ARENA_BANKS_DIRTY(R15)

	CMPQ    ACI_IS_FAST_PATH(AX), $2
	JNE     ci_full_register_alloc

	XORQ    CX, CX
	MOVQ    CX, CF_REGS_STRINGS_PTR(BX)
	MOVQ    CX, CF_REGS_STRINGS_LEN(BX)
	MOVQ    CX, CF_REGS_STRINGS_CAP(BX)
	MOVQ    CX, CF_REGS_GENERAL_PTR(BX)
	MOVQ    CX, CF_REGS_GENERAL_LEN(BX)
	MOVQ    CX, CF_REGS_GENERAL_CAP(BX)
	MOVQ    CX, CF_REGS_BOOLS_PTR(BX)
	MOVQ    CX, CF_REGS_BOOLS_LEN(BX)
	MOVQ    CX, CF_REGS_BOOLS_CAP(BX)
	MOVQ    CX, CF_REGS_UINTS_PTR(BX)
	MOVQ    CX, CF_REGS_UINTS_LEN(BX)
	MOVQ    CX, CF_REGS_UINTS_CAP(BX)
	MOVQ    CX, CF_REGS_COMPLEX_PTR(BX)
	MOVQ    CX, CF_REGS_COMPLEX_LEN(BX)
	MOVQ    CX, CF_REGS_COMPLEX_CAP(BX)
	MOVQ    CX, CF_REGS_SLICEBYTE_PTR(BX)
	MOVQ    CX, CF_REGS_SLICEBYTE_LEN(BX)
	MOVQ    CX, CF_REGS_SLICEBYTE_CAP(BX)
	JMP     ci_register_alloc_done

ci_full_register_alloc:
