// handlerReturnInline handles OpReturn with ASM-inlined fast path.
TEXT ·handlerReturnInline(SB), NOSPLIT|NOFRAME, $0
	MOVQ    CTX_FRAME_POINTER(R15), SI
	CMPQ    SI, CTX_BASE_FRAME_POINTER(R15)
	JLE     ri_fallback

	MOVQ    CTX_CSTACK_BASE(R15), BX
	MOVQ    $CALLFRAME_SIZE, CX
	MOVQ    SI, DI
	IMULQ   CX, DI
	LEAQ    (BX)(DI*1), DI

	MOVQ    CF_DEFERBASE(DI), CX
	CMPQ    CX, CTX_DEFER_STACK_LEN(R15)
	JNE     ri_fallback

	MOVQ    CF_SIMPLEDEFER(DI), CX
	TESTQ   CX, CX
	JZ      ri_no_simple_defer
	CMPB    SDR_ACTIVE(CX), $0
	JNE     ri_fallback
ri_no_simple_defer:

	CMPB    CF_ROOT_SWAPPED(DI), $0
	JNE     ri_fallback
	CMPQ    CF_SHARED_CELLS(DI), $0
	JNE     ri_fallback

	MOVL    DX, AX
	SHRL    $24, AX
	ANDL    $0xFF, AX

	LEAQ    -1(SI), R13
	MOVQ    $CALLFRAME_SIZE, CX
	MOVQ    R13, DX
	IMULQ   CX, DX
	LEAQ    (BX)(DX*1), R12

	TESTQ   AX, AX
	JZ      ri_no_retval
	CMPQ    AX, $1
	JNE     ri_multi

	MOVQ    CF_RETURNDEST_PTR(DI), CX
	TESTQ   CX, CX
	JZ      ri_fallback

	MOVBLZX VL_IS_UPVALUE(CX), AX
	TESTQ   AX, AX
	JNZ     ri_fallback

	MOVBLZX VL_KIND(CX), AX
	MOVBLZX VL_REGISTER(CX), CX

	CMPQ    AX, $0
	JE      ri_check_int
	CMPQ    AX, $1
	JE      ri_check_float
	CMPQ    AX, $2
	JE      ri_check_string
	CMPQ    AX, $4
	JE      ri_check_bool
	CMPQ    AX, $5
	JE      ri_check_uint
	CMPQ    AX, $3
	JE      ri_check_general
	JMP     ri_fallback

ri_check_int:
	CMPQ    CF_REGS_INTS_LEN(DI), $0
	JE      ri_fallback

ri_copy_int:
	MOVQ    CF_REGS_INTS_PTR(DI), AX
	MOVQ    (AX), AX
	MOVQ    CF_REGS_INTS_PTR(R12), BX
	MOVQ    AX, (BX)(CX*8)
	JMP     ri_no_retval

ri_check_float:
	CMPQ    CF_REGS_FLOATS_LEN(DI), $0
	JE      ri_fallback

ri_copy_float:
	MOVQ    CF_REGS_FLOATS_PTR(DI), AX
	MOVQ    (AX), AX
	MOVQ    CF_REGS_FLOATS_PTR(R12), BX
	MOVQ    AX, (BX)(CX*8)
	JMP     ri_no_retval

ri_check_string:
	CMPQ    CF_REGS_STRINGS_LEN(DI), $0
	JE      ri_fallback
	MOVQ    CF_REGS_STRINGS_PTR(DI), AX
	MOVQ    (AX), SI
	MOVQ    8(AX), AX
	MOVQ    CF_REGS_STRINGS_PTR(R12), BX
	SHLQ    $4, CX
	MOVQ    SI, (BX)(CX*1)
	MOVQ    AX, 8(BX)(CX*1)
	JMP     ri_no_retval

ri_check_bool:
	CMPQ    CF_REGS_BOOLS_LEN(DI), $0
	JE      ri_fallback
	MOVQ    CF_REGS_BOOLS_PTR(DI), AX
	MOVBLZX (AX), AX
	MOVQ    CF_REGS_BOOLS_PTR(R12), BX
	MOVB    AX, (BX)(CX*1)
	JMP     ri_no_retval

ri_check_uint:
	CMPQ    CF_REGS_UINTS_LEN(DI), $0
	JE      ri_fallback
	MOVQ    CF_REGS_UINTS_PTR(DI), AX
	MOVQ    (AX), AX
	MOVQ    CF_REGS_UINTS_PTR(R12), BX
	MOVQ    AX, (BX)(CX*8)
	JMP     ri_no_retval

ri_check_general:
	CMPB    runtime·writeBarrier(SB), $0
	JNE     ri_fallback
	CMPQ    CF_REGS_GENERAL_LEN(DI), $0
	JE      ri_fallback
	MOVQ    CF_REGS_GENERAL_PTR(DI), AX
	MOVQ    CF_REGS_GENERAL_PTR(R12), BX
	LEAQ    (CX)(CX*2), CX
	SHLQ    $3, CX
	ADDQ    CX, BX
	MOVQ    0(AX), CX
	MOVQ    CX, 0(BX)
	MOVQ    8(AX), CX
	MOVQ    CX, 8(BX)
	MOVQ    16(AX), CX
	MOVQ    CX, 16(BX)
	JMP     ri_no_retval

ri_multi:
	CMPQ    AX, $4
	JG      ri_fallback
	MOVQ    CF_FUNCTION(DI), SI
	CMPQ    AX, FN_RESULT_KINDS_LEN(SI)
	JG      ri_fallback
	MOVQ    AX, CTX_RET_COUNT(R15)
	MOVQ    $0, CTX_RET_INDEX(R15)
	MOVQ    $0, (CTX_RET_CURSORS+0)(R15)
	MOVQ    $0, (CTX_RET_CURSORS+8)(R15)
	MOVQ    $0, (CTX_RET_CURSORS+16)(R15)
	MOVQ    $0, (CTX_RET_CURSORS+24)(R15)
	MOVQ    $0, (CTX_RET_CURSORS+32)(R15)
	MOVQ    $0, (CTX_RET_CURSORS+40)(R15)

ri_multi_loop:
	MOVQ    CTX_RET_INDEX(R15), SI
	CMPQ    SI, CTX_RET_COUNT(R15)
	JGE     ri_no_retval
	CMPQ    SI, CF_RETURNDEST_LEN(DI)
	JGE     ri_no_retval
	MOVQ    $VL_SIZE, DX
	IMULQ   SI, DX
	ADDQ    CF_RETURNDEST_PTR(DI), DX
	MOVBLZX VL_IS_UPVALUE(DX), AX
	TESTQ   AX, AX
	JNZ     ri_fallback
	MOVBLZX VL_KIND(DX), AX
	MOVQ    CF_FUNCTION(DI), BX
	MOVQ    FN_RESULT_KINDS(BX), BX
	MOVBLZX (BX)(SI*1), BX
	CMPQ    AX, BX
	JNE     ri_fallback
	MOVBLZX VL_REGISTER(DX), CX
	LEAQ    CTX_RET_CURSORS(R15), DX
	MOVQ    (DX)(AX*8), BX
	INCQ    (DX)(AX*8)

	CMPQ    AX, $0
	JE      ri_multi_int
	CMPQ    AX, $1
	JE      ri_multi_float
	CMPQ    AX, $2
	JE      ri_multi_string
	CMPQ    AX, $4
	JE      ri_multi_bool
	CMPQ    AX, $5
	JE      ri_multi_uint
	JMP     ri_fallback

ri_multi_int:
	CMPQ    BX, CF_REGS_INTS_LEN(DI)
	JGE     ri_fallback
	MOVQ    CF_REGS_INTS_PTR(DI), AX
	MOVQ    (AX)(BX*8), AX
	MOVQ    CF_REGS_INTS_PTR(R12), DX
	MOVQ    AX, (DX)(CX*8)
	JMP     ri_multi_next

ri_multi_float:
	CMPQ    BX, CF_REGS_FLOATS_LEN(DI)
	JGE     ri_fallback
	MOVQ    CF_REGS_FLOATS_PTR(DI), AX
	MOVQ    (AX)(BX*8), AX
	MOVQ    CF_REGS_FLOATS_PTR(R12), DX
	MOVQ    AX, (DX)(CX*8)
	JMP     ri_multi_next

ri_multi_uint:
	CMPQ    BX, CF_REGS_UINTS_LEN(DI)
	JGE     ri_fallback
	MOVQ    CF_REGS_UINTS_PTR(DI), AX
	MOVQ    (AX)(BX*8), AX
	MOVQ    CF_REGS_UINTS_PTR(R12), DX
	MOVQ    AX, (DX)(CX*8)
	JMP     ri_multi_next

ri_multi_string:
	CMPQ    BX, CF_REGS_STRINGS_LEN(DI)
	JGE     ri_fallback
	SHLQ    $4, BX
	SHLQ    $4, CX
	MOVQ    CF_REGS_STRINGS_PTR(DI), AX
	MOVQ    (AX)(BX*1), SI
	MOVQ    8(AX)(BX*1), AX
	MOVQ    CF_REGS_STRINGS_PTR(R12), DX
	MOVQ    SI, (DX)(CX*1)
	MOVQ    AX, 8(DX)(CX*1)
	JMP     ri_multi_next

ri_multi_bool:
	CMPQ    BX, CF_REGS_BOOLS_LEN(DI)
	JGE     ri_fallback
	MOVQ    CF_REGS_BOOLS_PTR(DI), AX
	MOVBLZX (AX)(BX*1), AX
	MOVQ    CF_REGS_BOOLS_PTR(R12), DX
	MOVB    AX, (DX)(CX*1)

ri_multi_next:
	INCQ    CTX_RET_INDEX(R15)
	JMP     ri_multi_loop

ri_no_retval:
	MOVQ    CTX_ARENA_STR_IDX(R15), SI
	MOVQ    (CF_ARENA_SAVE+16)(DI), CX
	CMPQ    CX, SI
	JGE     ri_str_clear_done
	MOVQ    CTX_ARENA_STR_SLAB(R15), DX
	MOVQ    CX, AX
	SHLQ    $4, AX
	LEAQ    (DX)(AX*1), AX
	SHLQ    $4, SI
	LEAQ    (DX)(SI*1), SI

ri_str_clear_loop:
	MOVQ    $0, (AX)
	MOVQ    $0, 8(AX)
	ADDQ    $16, AX
	CMPQ    AX, SI
	JL      ri_str_clear_loop

ri_str_clear_done:
	MOVQ    (CF_ARENA_SAVE+0)(DI), AX
	MOVQ    AX, CTX_ARENA_INT_IDX(R15)
	MOVQ    (CF_ARENA_SAVE+8)(DI), AX
	MOVQ    AX, CTX_ARENA_FLT_IDX(R15)
	MOVQ    (CF_ARENA_SAVE+16)(DI), AX
	MOVQ    AX, CTX_ARENA_STR_IDX(R15)
	MOVQ    (CF_ARENA_SAVE+32)(DI), AX
	MOVQ    AX, CTX_ARENA_BOOL_IDX(R15)
	MOVQ    (CF_ARENA_SAVE+40)(DI), AX
	MOVQ    AX, CTX_ARENA_UINT_IDX(R15)
	MOVQ    (CF_ARENA_SAVE+96)(DI), AX
	MOVQ    AX, CTX_ARENA_SLICEBYTE_IDX(R15)
	MOVB    $1, CTX_ARENA_BANKS_DIRTY(R15)

	CMPB    CF_HAS_GENERAL_ALLOC(DI), $0
	JE      ri_gen_clear_done
	CMPB    runtime·writeBarrier(SB), $0
	JNE     ri_gen_clear_slow
	MOVQ    CF_ARENA_SAVE_GENERAL_IDX(DI), CX
	MOVQ    CTX_ARENA_GEN_IDX(R15), DX
	SUBQ    CX, DX
	JLE     ri_gen_clear_restore
	LEAQ    (CX)(CX*2), BX
	SHLQ    $3, BX
	ADDQ    CTX_ARENA_GENERAL_SLAB(R15), BX
	MOVQ    BX, SI
ri_gen_clear_zero:
	MOVQ    $0, (SI)
	MOVQ    $0, 8(SI)
	MOVQ    $0, 16(SI)
	ADDQ    $24, SI
	DECQ    DX
	JNZ     ri_gen_clear_zero
ri_gen_clear_restore:
	MOVQ    CX, CTX_ARENA_GEN_IDX(R15)
	MOVB    $1, CTX_ARENA_BANKS_DIRTY(R15)
	JMP     ri_gen_clear_done
ri_gen_clear_slow:
	CALL    ·handlerCallInlineClearGeneralBank(SB)
	MOVQ    CTX_FRAME_POINTER(R15), SI
	LEAQ    -1(SI), R13
	MOVQ    CTX_CSTACK_BASE(R15), BX
	MOVQ    $CALLFRAME_SIZE, CX
	MOVQ    R13, DX
	IMULQ   CX, DX
	LEAQ    (BX)(DX*1), R12
ri_gen_clear_done:

	MOVQ    R13, CTX_FRAME_POINTER(R15)
	MOVQ    R12, CTX_CURRENT_FRAME(R15)

	MOVQ    CTX_ASM_CI_PTRS(R15), AX
	MOVQ    (AX)(R13*8), AX
	MOVQ    AX, CTX_ASM_CALL_INFO_BASE(R15)

	MOVQ    CF_PROGRAM_COUNTER(R12), R14
	MOVQ    CF_REGS_INTS_PTR(R12), R8
	MOVQ    CF_REGS_FLOATS_PTR(R12), R9

	MOVQ    CF_REGS_STRINGS_PTR(R12), AX
	MOVQ    AX, CTX_STRINGS_BASE(R15)
	MOVQ    CF_REGS_UINTS_PTR(R12), AX
	MOVQ    AX, CTX_UINTS_BASE(R15)
	MOVQ    CF_REGS_BOOLS_PTR(R12), AX
	MOVQ    AX, CTX_BOOLS_BASE(R15)
	MOVQ    CF_REGS_GENERAL_PTR(R12), AX
	MOVQ    AX, CTX_GENERALS_BASE(R15)
	MOVQ    CF_REGS_SLICEBYTE_PTR(R12), AX
	MOVQ    AX, CTX_SLICES_BYTE_BASE(R15)
	MOVQ    CF_REGS_SLICESINT_PTR(R12), AX
	MOVQ    AX, CTX_SLICES_INT_BASE(R15)
	MOVQ    CF_REGS_SLICESFLOAT_PTR(R12), AX
	MOVQ    AX, CTX_SLICES_FLOAT_BASE(R15)
	MOVQ    CF_REGS_SLICESSTRING_PTR(R12), AX
	MOVQ    AX, CTX_SLICES_STRING_BASE(R15)
	MOVQ    CF_REGS_SLICESBOOL_PTR(R12), AX
	MOVQ    AX, CTX_SLICES_BOOL_BASE(R15)
	MOVQ    CF_REGS_SLICESUINT_PTR(R12), AX
	MOVQ    AX, CTX_SLICES_UINT_BASE(R15)
	MOVQ    CF_REGS_COMPLEX_PTR(R12), AX
	MOVQ    AX, CTX_COMPLEX_BASE(R15)

	MOVQ    CTX_DISPATCH_SAVES(R15), AX
	MOVQ    R13, CX
	SHLQ    $DS_SIZE_SHIFT, CX
	LEAQ    (AX)(CX*1), AX
	MOVQ    DS_CODE_BASE(AX), R12
	MOVQ    DS_CODE_LEN(AX), R13
	MOVQ    DS_INT_CONSTS(AX), R11
	MOVQ    DS_FLOAT_CONSTS(AX), CX
	MOVQ    CX, CTX_FLT_CONSTS_BASE(R15)
	MOVQ    DS_STRING_CONSTS(AX), CX
	MOVQ    CX, CTX_STR_CONSTS_BASE(R15)
	MOVQ    DS_BOOL_CONSTS(AX), CX
	MOVQ    CX, CTX_BOOL_CONSTS_BASE(R15)
	MOVQ    DS_UINT_CONSTS(AX), CX
	MOVQ    CX, CTX_UINT_CONSTS_BASE(R15)

	MOVQ    R12, CTX_CODE_BASE(R15)
	MOVQ    R13, CTX_CODE_LEN(R15)
	MOVQ    R14, CTX_PC(R15)
	MOVQ    R8, CTX_INTS_BASE(R15)
	MOVQ    R9, CTX_FLOATS_BASE(R15)
	MOVQ    R11, CTX_INT_CONSTS_BASE(R15)
	DISPATCH_NEXT()

ri_fallback:
	DECQ    R14
	MOVQ    R14, CTX_PC(R15)
	MOVQ    $EXIT_RETURN, CTX_EXIT_REASON(R15)
	MOVQ    R14, CTX_EXIT_PC(R15)
	RET     

